(()=>{const q=s=>document.querySelector(s),lines=['星光穿過古老的門扉，向你傳來一封遠征邀請。散落各地的星盤正在等待旅人重新點亮。','你將與劍士、弓箭手和法師結伴，穿越森語之境。夥伴會自動戰鬥；必殺技的施放時機，由你決定。','先使用100鑽石召喚第一位夥伴，再完成編隊與戰鬥教學。完成後可領取1,000鑽石，繼續召集隊伍。'];let index=0,busy=false;
function render(){const o=Onboarding.status(localStorage);if(o.intro){q('#continue').hidden=q('#skip').hidden=true;q('#next').hidden=false;q('#next').href=o.complete?'lobby.html':o.first?'portrait.html?tutorial=1':'summon.html';q('#next').textContent=o.complete?'教學已完成 · 前往大廳':o.first?'繼續編隊與戰鬥教學':'已領取100鑽 · 前往首次召喚';q('#story').textContent='你的遠征進度已保存，離開後可以回來接續。';q('#step').textContent='';return}q('#story').textContent=lines[index];q('#step').textContent=`介紹 ${index+1} / ${lines.length}`;q('#continue').textContent=index===2?'領取100鑽並開始':'繼續'}
async function claim(){if(busy)return;busy=true;try{if(!navigator.locks)throw Error('請使用新版瀏覽器');await navigator.locks.request(Summon.key,()=>Summon.intro(localStorage));location.href='summon.html'}catch(e){q('#notice').textContent='未完成領取：'+e.message}finally{busy=false}}
q('#continue').onclick=()=>{if(index===2)claim();else{index++;render()}};q('#skip').onclick=claim;try{render()}catch(e){q('#notice').textContent=e.message;q('#continue').disabled=q('#skip').disabled=true}
})();
